-- IAM catch-up: WorkflowReadinessPermission -> AddUserOtpsTable.
-- Generated by EF Core idempotent scripting; guarded per migration transaction.
-- Preserves unrelated migration history. Do not run concurrently with app migrations.
﻿START TRANSACTION;
SET LOCAL search_path TO public;
DO $preflight$
BEGIN
    IF to_regclass('public."__EFMigrationsHistory"') IS NULL THEN
        RAISE EXCEPTION 'IAM migration history is missing. Select the IAM database.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."__EFMigrationsHistory"
        WHERE migration_id = '20261016154952_WorkflowReadinessPermission') THEN
        RAISE EXCEPTION 'IAM baseline 20261016154952_WorkflowReadinessPermission is required.';
    END IF;
